enum LusterError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidSvg(reason: String
    )
    case InputTooComplex(reason: String
    )
    case NothingToMint
    case Cancelled
    case Internal(reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

