public struct FfiConverterTypeLusterError: FfiConverterRustBuffer {
    typealias SwiftType = LusterError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LusterError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidSvg(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InputTooComplex(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NothingToMint
        case 4: return .Cancelled
        case 5: return .Internal(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LusterError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidSvg(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .InputTooComplex(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NothingToMint:
            writeInt(&buf, Int32(3))
        
        
        case .Cancelled:
            writeInt(&buf, Int32(4))
        
        
        case let .Internal(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


